public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> results = new ArrayList<>();
    if (nums == null) {
        return results;
    }
    int n = nums.length;
    boolean[] used = new boolean[n];
    List<Integer> current = new ArrayList<>(n);
    backtrack(nums, n, used, current, results);
    return results;
}

private void backtrack(int[] nums, int n, boolean[] used, List<Integer> current,
                       List<List<Integer>> results) {
    if (current.size() == n) {
        results.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, n, used, current, results);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

