public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    Set<String> substrings = new HashSet<>();
    for (String s : strings) {
        if (s == null) continue;
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                substrings.add(s.substring(i, j));
            }
        }
    }
    int maxLen = 0;
    for (String sub : substrings) {
        String reverse = new StringBuilder(sub).reverse().toString();
        if (substrings.contains(reverse)) {
            if (sub.length() > maxLen) {
                maxLen = sub.length();
            }
        }
    }
    return maxLen;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    if (first == null) {
        first = "";
    }
    int maxLen = 0;
    int n = first.length();
    Set<String> seen = new HashSet<>();
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j <= n; j++) {
            String sub = first.substring(i, j);
            if (!seen.add(sub)) {
                continue; // already processed
            }
            String revSub = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (int k = 1; k < strings.size(); k++) {
                String s = strings.get(k);
                if (s == null) {
                    s = "";
                }
                if (!(s.contains(sub) || s.contains(revSub))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                maxLen = Math.max(maxLen, sub.length());
            }
        }
    }
    return maxLen;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Determine the maximum possible length by the shortest string
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) s = "";
        if (s.length() < minLen) {
            minLen = s.length();
        }
    }
    if (minLen == 0) {
        return 0;
    }
    // Reference string for generating candidate substrings
    String ref = strings.get(0);
    if (ref == null) ref = "";
    for (int len = minLen; len >= 1; len--) {
        // All unique substrings of length len from the reference string
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i + len <= ref.length(); i++) {
            candidates.add(ref.substring(i, i + len));
        }
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (s == null) s = "";
                if (!s.contains(cand) && !s.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find the shortest string to reduce candidate substrings
    String reference = null;
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            continue;
        }
        if (s.length() < minLen) {
            minLen = s.length();
            reference = s;
        }
    }
    if (reference == null || reference.isEmpty()) {
        return 0;
    }

    int refLen = reference.length();

    for (int len = refLen; len >= 1; len--) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        for (int i = 0; i + len <= refLen; i++) {
            String candidate = reference.substring(i, i + len);
            if (!seen.add(candidate)) {
                continue; // already checked this substring
            }
            String reversed = new StringBuilder(candidate).reverse().toString();

            boolean valid = true;
            for (String s : strings) {
                if (s == null) { // treat null as empty string
                    valid = false;
                    break;
                }
                if (!(s.contains(candidate) || s.contains(reversed))) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.size() < 2) {
        return 0;
    }
    Map<String, Set<Integer>> map = new HashMap<>();
    int n = strings.size();
    for (int i = 0; i < n; i++) {
        String s = strings.get(i);
        if (s == null) {
            continue;
        }
        int len = s.length();
        Set<String> seen = new HashSet<>();
        for (int start = 0; start < len; start++) {
            for (int end = start + 1; end <= len; end++) {
                String sub = s.substring(start, end);
                if (seen.add(sub)) {
                    // Add the substring itself
                    map.computeIfAbsent(sub, k -> new HashSet<>()).add(i);
                    // Add the reverse of the substring
                    String rev = new StringBuilder(sub).reverse().toString();
                    map.computeIfAbsent(rev, k -> new HashSet<>()).add(i);
                }
            }
        }
    }

    int maxLen = 0;
    for (Map.Entry<String, Set<Integer>> entry : map.entrySet()) {
        Set<Integer> indices = entry.getValue();
        if (indices.size() >= 2) {
            int curLen = entry.getKey().length();
            if (curLen > maxLen) {
                maxLen = curLen;
            }
        }
    }
    return maxLen;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int[][] visited = new int[rows][];
    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) {
            visited[r] = new int[0];
            continue;
        }
        visited[r] = new int[grid[r].length];
    }

    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    int deposits = 0;

    for (int r = 0; r < rows; r++) {
        int cols = grid[r] == null ? 0 : grid[r].length;
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && visited[r][c] == 0) {
                deposits++;
                // BFS
                java.util.ArrayDeque<int[]> dq = new java.util.ArrayDeque<>();
                dq.add(new int[]{r, c});
                visited[r][c] = 1;
                while (!dq.isEmpty()) {
                    int[] cur = dq.poll();
                    int cr = cur[0], cc = cur[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dr[k];
                        int nc = cc + dc[k];
                        if (nr < 0 || nr >= rows) continue;
                        if (grid[nr] == null || nc < 0 || nc >= grid[nr].length) continue;
                        if (grid[nr][nc] == '@' && visited[nr][nc] == 0) {
                            visited[nr][nc] = 1;
                            dq.add(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

public static int countOilDeposits(char[][] grid) {
    // Validate input
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int rows = grid.length;
    // Prepare visited array respecting variable row lengths
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        char[] row = grid[i];
        visited[i] = (row == null) ? new boolean[0] : new boolean[row.length];
    }

    // 8-direction offsets
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    int deposits = 0;

    for (int r = 0; r < rows; r++) {
        char[] currRow = grid[r];
        if (currRow == null) continue;
        int cols = currRow.length;

        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;

                // BFS/DFS stack
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;

                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0], cc = pos[1];

                    for (int d = 0; d < 8; d++) {
                        int nr = cr + dx[d];
                        int nc = cc + dy[d];

                        if (nr < 0 || nr >= rows) continue;
                        if (grid[nr] == null) continue;
                        if (nc < 0 || nc >= grid[nr].length) continue;
                        if (visited[nr][nc]) continue;
                        if (grid[nr][nc] != '@') continue;

                        visited[nr][nc] = true;
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
        }
    }

    return deposits;
}

