                    java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                    stack.push(new int[] { r, c });
                    visited[r][c] = true;
                    while (!stack.isEmpty()) {
                        int[] pos = stack.pop();
                        int cr = pos[0], cc = pos[1];
                        for (int d = 0; d < 8; d++) {
                            int nr = cr + dr[d];
                            int nc = cc + dc[d];
                            if (nr < 0 || nr >= rows) {
                                continue;
                            }
                            if (grid[nr] == null) {
                                continue;
                            }
                            if (nc < 0 || nc >= grid[nr].length) {
                                continue;
                            }
                            if (!visited[nr][nc] && grid[nr][nc] == '@') {
                                visited[nr][nc] = true;
                                stack.push(new int[] { nr, nc });
                            }
                        }
                    }
                }
            }
        }
        return count;
    } catch (Exception e) {
        return 0;
    }
}

public static int maxRegions(int N) {
    if (N <= 0) {
        return 1; // No triangles: only one unbounded region
    }
    long n = N;
    long regions = 3L * n * (n - 1) + 2;
    if (regions > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds integer range");
    }
    return (int) regions;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1; // no triangles, the plane is one region
    }
    long regions = 3L * N * (long) (N - 1) + 2L;
    if (regions > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
    }
    return (int) regions;
}

