public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    if (paths == null) {
        return "cannot be travelled";
    }
    int dim = start.length;
    if (end.length != dim) {
        return "cannot be travelled";
    }
    // If start equals end, travel is possible
    if (java.util.Arrays.equals(start, end)) {
        return "can be travelled";
    }

    // Build adjacency map by interpreting each path entry as a pair of coordinates
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] entry : paths) {
        if (entry == null) continue;
        if (entry.length != 2 * dim) {
            // Inconsistent entry length; skip
            continue;
        }
        // First half is first coordinate, second half is second coordinate
        int[] a = new int[dim];
        int[] b = new int[dim];
        System.arraycopy(entry, 0, a, 0, dim);
        System.arraycopy(entry, dim, b, 0, dim);
        String sa = key(a);
        String sb = key(b);
        adj.computeIfAbsent(sa, k -> new java.util.ArrayList<>()).add(sb);
        adj.computeIfAbsent(sb, k -> new java.util.ArrayList<>()).add(sa);
    }

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    String startKey = key(start);
    String endKey = key(end);
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

private static String key(int[] coord) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < coord.length; i++) {
        if (i > 0) sb.append(',');
        sb.append(coord[i]);
    }
    return sb.toString();
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input parameters
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    // Helper to convert an array of coordinates to a unique string key
    java.util.function.Function<int[], String> coordToKey = coords -> {
        if (coords == null || coords.length == 0) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coords.length; i++) {
            if (i > 0) sb.append(",");
            sb.append(coords[i]);
        }
        return sb.toString();
    };

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    // If start and end are identical, traversal is trivially possible
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency list
    java.util.Map<String, java.util.Set<String>> adj = new java.util.HashMap<>();

    // Helper to add node if not present
    java.util.function.Consumer<String> addNode = key -> adj.computeIfAbsent(key, k -> new java.util.HashSet<>());

    // Add start and end nodes to the set
    addNode.accept(startKey);
    addNode.accept(endKey);

    for (int[] path : paths) {
        if (path == null) continue;

        // Interpret path as either two node ids (length 2) or two coordinate pairs (length 4)
        String node1 = null;
        String node2 = null;

        if (path.length == 2) {
            // Treat each integer as a node identifier
            node1 = String.valueOf(path[0]);
            node2 = String.valueOf(path[1]);
        } else if (path.length == 4) {
            int[] pair1 = new int[]{path[0], path[1]};
            int[] pair2 = new int[]{path[2], path[3]};
            node1 = coordToKey.apply(pair1);
            node2 = coordToKey.apply(pair2);
        } else {
            // Unsupported format; skip this path
            continue;
        }

        if (node1 == null || node2 == null) continue;

        // Add nodes to adjacency map if necessary
        addNode.accept(node1);
        addNode.accept(node2);

        // Undirected edge
        adj.get(node1).add(node2);
        adj.get(node2).add(node1);
    }

    // Breadth-First Search to determine reachability
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.Set<String> neighbors = adj.getOrDefault(current, java.util.Collections.emptySet());
        for (String neighbor : neighbors) {
            if (neighbor.equals(endKey)) {
                return "can be travelled";
            }
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        // Basic validation
        if (n <= 0 || start == null || end == null || paths == null) {
            return "cannot be travelled";
        }
        if (start.length != 2 || end.length != 2) {
            return "cannot be travelled";
        }
        int sx = start[0], sy = start[1];
        int ex = end[0], ey = end[1];
        if (sx < 0 || sx >= n || sy < 0 || sy >= n ||
            ex < 0 || ex >= n || ey < 0 || ey >= n) {
            return "cannot be travelled";
        }
        // Special case: start equals end
        if (sx == ex && sy == ey) {
            return "can be travelled";
        }

        // Build adjacency map
        java.util.Map<Integer, java.util.List<Integer>> adj = new java.util.HashMap<>();
        int nodeId(int x, int y) { return x * n + y; }

        for (int[] p : paths) {
            if (p == null || p.length != 4) {
                return "cannot be travelled";
            }
            int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n ||
                x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                return "cannot be travelled";
            }
            // Ensure adjacency: must differ by exactly 1 in one coordinate
            int dx = Math.abs(x1 - x2), dy = Math.abs(y1 - y2);
            if (!((dx == 1 && dy == 0) || (dx == 0 && dy == 1))) {
                return "cannot be travelled";
            }
            int id1 = nodeId(x1, y1);
            int id2 = nodeId(x2, y2);
            adj.computeIfAbsent(id1, k -> new java.util.ArrayList<>()).add(id2);
            adj.computeIfAbsent(id2, k -> new java.util.ArrayList<>()).add(id1);
        }

        int startId = nodeId(sx, sy);
        int endId = nodeId(ex, ey);

        // BFS
        java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
        java.util.Set<Integer> visited = new java.util.HashSet<>();
        queue.add(startId);
        visited.add(startId);

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (cur == endId) {
                return "can be travelled";
            }
            java.util.List<Integer> neighbors = adj.getOrDefault(cur, java.util.Collections.emptyList());
            for (int nb : neighbors) {
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    queue.add(nb);
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        // Any unexpected issue results in inability to travel
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        // Basic validation of inputs
        if (n <= 0 || start == null || end == null || start.length == 0 || end.length == 0) {
            return "cannot be travelled";
        }

        int startNode = start[0];
        int endNode = end[0];

        if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
            return "cannot be travelled";
        }

        // Quick check if start and end are the same
        if (startNode == endNode) {
            return "can be travelled";
        }

        // Build adjacency list for undirected graph
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new java.util.ArrayList<>();
        }

        if (paths != null) {
            for (int[] edge : paths) {
                if (edge == null || edge.length < 2) {
                    continue; // skip malformed entries
                }
                int u = edge[0];
                int v = edge[1];
                if (u < 0 || u >= n || v < 0 || v >= n) {
                    continue; // skip out-of-bounds edges
                }
                adj[u].add(v);
                adj[v].add(u); // undirected
            }
        }

        // BFS to find if a path exists
        boolean[] visited = new boolean[n];
        java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
        visited[startNode] = true;
        queue.offer(startNode);

        while (!queue.isEmpty()) {
            int current = queue.poll();
            for (int neighbor : adj[current]) {
                if (!visited[neighbor]) {
                    if (neighbor == endNode) {
                        return "can be travelled";
                    }
                    visited[neighbor] = true;
                    queue.offer(neighbor);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // Any unexpected error results in not being able to travel
        return "cannot be travelled";
    }
}

