public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return "Invalid Input";
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return "Invalid Input";
    }
    int month, day, year;
    try {
        month = Integer.parseInt(parts[0]);
        day = Integer.parseInt(parts[1]);
        year = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        return "Invalid Input";
    }
    try {
        java.time.LocalDate ld = java.time.LocalDate.of(year, month, day);
        String monthName = ld.getMonth().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String dayName = ld.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        return String.format("%s %d, %d is a %s", monthName, ld.getDayOfMonth(), ld.getYear(), dayName);
    } catch (Exception e) {
        return "Invalid Input";
    }
}

