public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false; // division by zero or negative divisor is not supported
    }
    int n = arr.length;
    int[] freq = new int[k];
    for (int value : arr) {
        int rem = ((value % k) + k) % k; // ensure non-negative remainder
        freq[rem]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check remainder k/2 when k is even
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For all other remainders, freq[r] must equal freq[k - r]
    for (int r = 1; r < k; r++) {
        int complement = k - r;
        if (r > complement) {
            continue; // already checked pair when r was smaller
        }
        if (freq[r] != freq[complement]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    // If number of elements is odd, cannot form n/2 pairs
    if (n % 2 != 0) {
        return false;
    }
    // Count occurrences of each remainder
    int[] remainderCount = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k; // ensure positive remainder
        }
        remainderCount[r]++;
    }
    // Check remainder 0 pairs (need even count)
    if (remainderCount[0] % 2 != 0) {
        return false;
    }
    // If k is even, also check remainder k/2 pairs
    if (k % 2 == 0) {
        if (remainderCount[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For other remainders, counts must match complementary remainder
    int limit = k / 2;
    if (k % 2 == 0) {
        limit -= 1; // exclude k/2 already handled
    }
    for (int r = 1; r <= limit; r++) {
        if (remainderCount[r] != remainderCount[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Handle null or non-positive divisor
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    // Pairing possible only if length is even
    if (n % 2 != 0) {
        return false;
    }
    // Empty array can trivially be partitioned into zero pairs
    if (n == 0) {
        return true;
    }

    // Count remainders using a HashMap
    java.util.Map<Integer, Integer> remainderCount = new java.util.HashMap<>(k * 2);
    for (int num : arr) {
        int r = Math.floorMod(num, k); // ensures non-negative remainder
        remainderCount.merge(r, 1, Integer::sum);
    }

    // Verify pairing conditions
    for (java.util.Map.Entry<Integer, Integer> entry : remainderCount.entrySet()) {
        int r = entry.getKey();
        int count = entry.getValue();
        int complement = (k - r) % k; // complement remainder

        if (r == complement) {
            if ((count & 1) == 1) { // odd count for 0 or k/2 remainders
                return false;
            }
        } else {
            int complementCount = remainderCount.getOrDefault(complement, 0);
            if (count != complementCount) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k == 0) {
        return false; // invalid input or divisor zero
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot pair odd number of elements
    }

    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : arr) {
        // Compute a non‑negative remainder in the range [0, |k|-1]
        int r = java.lang.Math.floorMod(num, k);
        freq.put(r, freq.getOrDefault(r, 0) + 1);
    }

    java.util.Set<Integer> visited = new java.util.HashSet<>();
    for (int r : freq.keySet()) {
        if (visited.contains(r)) {
            continue;
        }

        int countR = freq.get(r);
        // Complement remainder that pairs with r
        int complement = java.lang.Math.floorMod(-r, k);

        if (!freq.containsKey(complement)) {
            return false; // missing partner
        }

        // If r and its complement are the same (e.g., r == 0 or k even && r == k/2)
        if (r == complement) {
            if (countR % 2 != 0) {
                return false; // need even count to form pairs
            }
        } else {
            int countC = freq.get(complement);
            if (countR != countC) {
                return false; // counts must match
            }
        }

        visited.add(r);
        visited.add(complement);
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) {
        return false;
    }
    int n = arr.length;
    if (n == 0) {
        return true; // No elements to pair
    }
    if (n % 2 != 0) {
        return false; // Can't form pairs with odd number of elements
    }
    if (k <= 0) {
        return false; // Divisor must be positive
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k; // ensure non‑negative remainder
        }
        freq[r]++;
    }

    // Remainder 0 must pair amongst itself
    if (freq[0] % 2 != 0) {
        return false;
    }

    // If k is even, the remainder k/2 must also pair amongst itself
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }

    // For other remainders, freq[r] must equal freq[k - r]
    int upper = (k + 1) / 2; // exclusive upper bound for loop
    for (int r = 1; r < upper; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("Invalid input parameters.");
    }
    // Build adjacency list
    @SuppressWarnings("unchecked")
    java.util.ArrayList<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    if (edges != null) {
        for (int[] edge : edges) {
            if (edge == null || edge.length != 2) {
                throw new IllegalArgumentException("Each edge must contain exactly two vertices.");
            }
            int u = edge[0], v = edge[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                throw new IllegalArgumentException("Edge vertices out of bounds.");
            }
            graph[u].add(v);
            graph[v].add(u);
        }
    }
    // DFS to compute required time
    int[] total = {0};
    boolean[] visited = new boolean[n];

    java.util.function.Function<Integer, Boolean> dfs = new java.util.function.Function<Integer, Boolean>() {
        @Override
        public Boolean apply(Integer node) {
            visited[node] = true;
            boolean hasInSubtree = hasApple[node];
            for (int nei : graph[node]) {
                if (!visited[nei]) {
                    boolean childHasApple = apply(nei);
                    if (childHasApple) {
                        total[0] += 2; // travel to child and back
                        hasInSubtree = true;
                    }
                }
            }
            return hasInSubtree;
        }
    };

    dfs.apply(0);

    // If root has no apple and no necessary edges, total will be 0
    return total[0];
}

