            int u = e[0], v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            graph[u].add(v);
            graph[v].add(u);
        }
    }
    int[] total = new int[1];
    dfs(0, -1, graph, hasApple, total);
    return total[0];
}

private boolean dfs(int node, int parent, java.util.List<Integer>[] graph, boolean[] hasApple, int[] total) {
    boolean found = hasApple[node];
    for (int nei : graph[node]) {
        if (nei == parent) continue;
        if (dfs(nei, node, graph, hasApple, total)) {
            total[0] += 2;
            found = true;
        }
    }
    return found;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) {
        return 0;
    }
    if (edges == null || edges.length != n - 1) {
        return 0;
    }
    if (hasApple == null || hasApple.length != n) {
        return 0;
    }
    // Build adjacency list
    java.util.List<Integer>[] graph = (java.util.List<Integer>[]) new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<Integer>();
    }
    try {
        for (int[] edge : edges) {
            if (edge == null || edge.length != 2) {
                continue;
            }
            int u = edge[0];
            int v = edge[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                continue;
            }
            graph[u].add(v);
            graph[v].add(u);
        }
    } catch (RuntimeException e) {
        return 0;
    }

    // Parent array for tree traversal
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -2); // -2 indicates unvisited
    parent[0] = -1;

    // Stack for DFS traversal
    int[] stack = new int[n];
    int sp = 0;
    stack[sp++] = 0;

    // Order array to process nodes in post-order
    int[] order = new int[n];
    int orderIdx = 0;

    while (sp > 0) {
        int u = stack[--sp];
        order[orderIdx++] = u;
        for (int v : graph[u]) {
            if (parent[v] == -2) {
                parent[v] = u;
                stack[sp++] = v;
            }
        }
    }

    int[] cost = new int[n];
    boolean[] needed = new boolean[n];

    for (int i = orderIdx - 1; i >= 0; i--) {
        int u = order[i];
        boolean hasInSubtree = hasApple[u];
        int subCost = 0;
        for (int v : graph[u]) {
            if (v == parent[u]) {
                continue;
            }
            if (needed[v]) {
                hasInSubtree = true;
                subCost += cost[v] + 2;
            }
        }
        needed[u] = hasInSubtree;
        cost[u] = subCost;
    }

    return cost[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Handle invalid inputs gracefully
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        return 0;
    }

    // Build adjacency list
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length != 2) continue;
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        graph[u].add(v);
        graph[v].add(u);
    }

    // Parent array to avoid revisiting
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);

    // Two stacks for iterative post-order traversal
    java.util.Deque<Integer> stack = new java.util.LinkedList<>();
    java.util.Deque<Integer> postOrder = new java.util.LinkedList<>();
    stack.push(0);

    while (!stack.isEmpty()) {
        int node = stack.pop();
        postOrder.push(node);
        for (int child : graph[node]) {
            if (child != parent[node]) {
                parent[child] = node;
                stack.push(child);
            }
        }
    }

    int totalTime = 0;
    boolean[] hasSub = new boolean[n];

    while (!postOrder.isEmpty()) {
        int node = postOrder.pop();
        boolean has = hasApple[node];
        for (int child : graph[node]) {
            if (child != parent[node] && hasSub[child]) {
                has = true;
                totalTime += 2; // traverse to child and back
            }
        }
        hasSub[node] = has;
    }

    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) return 0;
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new java.util.ArrayList<>();
    if (edges != null) {
        for (int[] edge : edges) {
            if (edge == null || edge.length < 2) continue;
            int u = edge[0], v = edge[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            graph[u].add(v);
            graph[v].add(u);
        }
    }
    int[] parent = new int[n];
    int[] order = new int[n];
    int idx = 0;
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    parent[0] = -1;
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int child : graph[node]) {
            if (child == parent[node]) continue;
            parent[child] = node;
            stack.push(child);
        }
    }
    boolean[] need = new boolean[n];
    System.arraycopy(hasApple, 0, need, 0, n);
    int total = 0;
    for (int i = idx - 1; i >= 0; --i) {
        int node = order[i];
        if (node == 0) continue;
        if (need[node]) {
            total += 2;
            need[parent[node]] = true;
        }
    }
    return total;
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        if (c < 'a' || c > 'z') {
            throw new IllegalArgumentException("String must contain only lowercase letters a-z");
        }
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // ascending pass
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // descending pass
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null) return null;
    int n = s.length();
    int[] cnt = new int[26];
    for (char ch : s.toCharArray()) {
        cnt[ch - 'a']++;
    }
    StringBuilder sb = new StringBuilder(n);
    int remaining = n;

    while (remaining > 0) {
        // Phase 1: increasing order
        int i = 0;
        while (i < 26 && cnt[i] == 0) i++;
        if (i < 26) {
            sb.append((char) (i + 'a'));
            cnt[i]--;
            remaining--;
            int last = i;
            for (int j = last + 1; j < 26; j++) {
                if (cnt[j] > 0) {
                    sb.append((char) (j + 'a'));
                    cnt[j]--;
                    remaining--;
                    last = j;
                }
            }
        }

        // Phase 2: decreasing order
        int j = 25;
        while (j >= 0 && cnt[j] == 0) j--;
        if (j >= 0) {
            sb.append((char) (j + 'a'));
            cnt[j]--;
            remaining--;
            int last = j;
            for (int k = last - 1; k >= 0; k--) {
                if (cnt[k] > 0) {
                    sb.append((char) (k + 'a'));
                    cnt[k]--;
                    remaining--;
                    last = k;
                }
            }
        }
    }

    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.merge(c, 1, Integer::sum);
    }
    StringBuilder result = new StringBuilder();
    while (!freq.isEmpty()) {
        // Pick the smallest character
        java.util.Map.Entry<Character, Integer> smallestEntry = freq.firstEntry();
        char last = smallestEntry.getKey();
        result.append(last);
        int cnt = smallestEntry.getValue();
        if (cnt == 1) {
            freq.remove(last);
        } else {
            freq.put(last, cnt - 1);
        }

        // Pick characters greater than last in ascending order
        while (true) {
            java.util.Map.Entry<Character, Integer> nextEntry = freq.higherEntry(last);
            if (nextEntry == null) {
                break;
            }
            last = nextEntry.getKey();
            result.append(last);
            int ncnt = nextEntry.getValue();
            if (ncnt == 1) {
                freq.remove(last);
            } else {
                freq.put(last, ncnt - 1);
            }
        }

        // If all characters are used, break
        if (freq.isEmpty()) {
            break;
        }

        // Pick the largest character
        java.util.Map.Entry<Character, Integer> largestEntry = freq.lastEntry();
        last = largestEntry.getKey();
        result.append(last);
        int lcnt = largestEntry.getValue();
        if (lcnt == 1) {
            freq.remove(last);
        } else {
            freq.put(last, lcnt - 1);
        }

        // Pick characters smaller than last in descending order
        while (true) {
            java.util.Map.Entry<Character, Integer> prevEntry = freq.lowerEntry(last);
            if (prevEntry == null) {
                break;
            }
            last = prevEntry.getKey();
            result.append(last);
            int pcnt = prevEntry.getValue();
            if (pcnt == 1) {
                freq.remove(last);
            } else {
                freq.put(last, pcnt - 1);
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
