    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }
    StringBuilder result = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending phase
        Character key = freq.firstKey();
        result.append(key);
        int cnt = freq.get(key);
        if (cnt == 1) {
            freq.remove(key);
        } else {
            freq.put(key, cnt - 1);
        }
        char last = key;
        while (true) {
