            if (entry == null) {
                break;
            }
            key = entry.getKey();
            result.append(key);
            cnt = entry.getValue();
            if (cnt == 1) {
                freq.remove(key);
            } else {
                freq.put(key, cnt - 1);
            }
            last = key;
        }
        if (freq.isEmpty()) {
            break;
        }

        // Descending phase
        key = freq.lastKey();
        result.append(key);
        cnt = freq.get(key);
        if (cnt == 1) {
            freq.remove(key);
        } else {
            freq.put(key, cnt - 1);
