        }
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    TreeMap<Character, Integer> counts = new TreeMap<>();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        counts.merge(c, 1, Integer::sum);
    }

    StringBuilder sb = new StringBuilder();
    while (!counts.isEmpty()) {
        // Ascending sequence
        Character curr = counts.firstKey();
        while (curr != null) {
            sb.append(curr);
            int newCnt = counts.get(curr) - 1;
            if (newCnt == 0) {
                counts.remove(curr);
            } else {
                counts.put(curr, newCnt);
            }
            curr = counts.higherKey(curr);
        }

        if (counts.isEmpty()) {
            break;
        }

        // Descending sequence
        curr = counts.lastKey();
        while (curr != null) {
            sb.append(curr);
            int newCnt = counts.get(curr) - 1;
            if (newCnt == 0) {
                counts.remove(curr);
            } else {
                counts.put(curr, newCnt);
            }
            curr = counts.lowerKey(curr);
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }
    // dp[k][s] indicates whether a subset of size k with sum s is attainable
    // We only need sizes up to n/2 due to symmetry
    int maxK = n / 2;
    boolean[][] dp = new boolean[maxK + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate k descending to avoid reuse
        for (int k = Math.min(maxK, n - 1); k >= 1; k--) {
            for (int s = totalSum; s >= num; s--) {
                if (dp[k - 1][s - num]) {
                    dp[k][s] = true;
                }
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        long prod = (long) totalSum * k;
        if (prod % n != 0) {
            continue;
        }
        int target = (int) (prod / n);
        if (dp[k][target]) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // try each possible subset size
    for (int k = 1; k <= n / 2; k++) {
        long tTimesN = (long) totalSum * k;
        if (tTimesN % n != 0) continue;
        int target = (int) (tTimesN / n);
        @SuppressWarnings("unchecked")
        Set<Integer>[] dp = new Set[k + 1];
        for (int i = 0; i <= k; i++) dp[i] = new HashSet<>();
        dp[0].add(0);
        for (int num : nums) {
            for (int size = k; size >= 1; size--) {
                if (dp[size - 1].isEmpty()) continue;
                for (int sum : dp[size - 1]) {
                    int newSum = sum + num;
                    if (newSum <= target) dp[size].add(newSum);
                }
            }
            if (dp[k].contains(target)) return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }
    int maxK = n / 2;

    // dp[k] stores all possible sums achievable by a subset of size k
    @SuppressWarnings("unchecked")
    Set<Long>[] dp = new Set[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0L);

    int processed = 0;
    for (int num : nums) {
        // update dp from larger k to smaller to avoid using the same number twice
        for (int k = Math.min(processed + 1, maxK); k >= 1; k--) {
            Set<Long> prev = dp[k - 1];
            if (prev.isEmpty()) {
                continue;
            }
            Set<Long> cur = dp[k];
            for (long s : prev) {
                cur.add(s + num);
            }
        }

        // After adding the current number, check all possible subset sizes
        for (int k = 1; k <= maxK; k++) {
            if (((long) totalSum * k) % n != 0) {
                continue; // target sum would not be integer
            }
            long target = ((long) totalSum * k) / n;
            if (dp[k].contains(target)) {
                return true;
            }
        }
        processed++;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    long total = 0;
    for (int v : nums) total += v;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Long>[] subsets = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) subsets[i] = new java.util.HashSet<>();
    dfs(nums, 0, 0L, 0, subsets);
    for (int k = 1; k <= n / 2; k++) {
        if ((total * k) % n != 0) continue;
        long target = total * k / n;
        if (subsets[k].contains(target)) return true;
    }
    return false;
}

private void dfs(int[] nums, int idx, long sum, int count, java.util.HashSet<Long>[] subsets) {
    if (idx == nums.length) {
        subsets[count].add(sum);
        return;
    }
    dfs(nums, idx + 1, sum + nums[idx], count + 1, subsets);
    dfs(nums, idx + 1, sum, count, subsets);
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false; // need two non‑empty parts
    }
    long totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }

    // dp[k] holds all achievable sums using exactly k numbers
    @SuppressWarnings("unchecked")
    Set<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);

    int maxK = n / 2; // we only need to consider subset sizes up to n/2
    for (int num : nums) {
        // iterate sizes in reverse so that we use each number only once
        for (int k = Math.min(maxK, n); k >= 1; k--) {
            if (dp[k - 1].isEmpty()) {
                continue;
            }
            for (int sum : dp[k - 1]) {
                dp[k].add(sum + num);
            }
        }
    }

    for (int k = 1; k <= maxK; k++) {
        long product = totalSum * k;
        if (product % n != 0) {
            continue; // target sum not integer
        }
        int target = (int) (product / n);
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }
    return Math.min(dp[n], dp[n - 1]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1, prev2) + cost[i - 1];
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }

    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        // Can start at the top without paying any step cost.
        return 0;
    }
    // Use two variables to store the minimal cost to reach the previous two steps.
    int costPrevPrev = cost[0]; // dp[0]
    int costPrev = cost[1];     // dp[1]
    int currentCost = 0;
    for (int i = 2; i < n; i++) {
        currentCost = cost[i] + Math.min(costPrev, costPrevPrev);
        costPrevPrev = costPrev;
        costPrev = currentCost;
    }
    // The top is just beyond the last step; we can arrive from the last or second last step.
    return Math.min(costPrev, costPrevPrev);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    int prev2 = 0; // cost to reach step i-2 (or start)
    int prev1 = 0; // cost to reach step i-1 (or start)
    for (int i = 2; i <= n; i++) {
        int costFromPrev = prev1 + cost[i - 1];
        int costFromPrevPrev = prev2 + cost[i - 2];
        int current = Math.min(costFromPrev, costFromPrevPrev);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

