public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    if (s.length() < k) {
        return false;
    }
    // Prevent shifting by 31 or more bits which would cause overflow
    if (k >= 31) {
        return false;
    }
    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int count = 0;
    int mask = totalCodes - 1;
    int current = 0;
    for (int i = 0; i < s.length(); i++) {
        int bit = s.charAt(i) - '0';
        current = ((current << 1) & mask) | bit;
        if (i >= k - 1) {
            if (!seen[current]) {
                seen[current] = true;
                count++;
                if (count == totalCodes) {
                    return true;
                }
            }
        }
    }
    return count == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) return false;
    if (k == 0) return true; // only empty string
    int n = s.length();
    if (n < k) return false;

    int total = 1 << k;          // total number of binary codes of length k
    boolean[] seen = new boolean[total];
    int seenCount = 0;
    int mask = total - 1;        // keeps only k bits

    int current = 0;
    for (int i = 0; i < n; i++) {
        current = ((current << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {        // we have a full window
            if (!seen[current]) {
                seen[current] = true;
                seenCount++;
                if (seenCount == total) {
                    return true;   // all codes found
                }
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    // Handle edge cases
    if (k <= 0) {
        return true; // Empty code is trivially present
    }
    int n = s == null ? 0 : s.length();
    if (n < k) {
        return false;
    }

    // Prevent overflow on mask when k is large
    if (k >= 31) {
        // For k >= 31, 2^k is astronomically large; practically impossible to verify.
        // We assume such inputs are invalid and return false.
        return false;
    }

    // Prepare variables for sliding window
    int totalCodes = 1 << k;                  // 2^k
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;                // Keep only k bits

    // Build first window
    int cur = 0;
    for (int i = 0; i < k; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            throw new IllegalArgumentException("Input string contains non-binary character");
        }
        cur = ((cur << 1) | (c - '0')) & mask;
    }
    seen[cur] = true;
    int found = 1;

    // Slide through the string
    for (int i = k; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            throw new IllegalArgumentException("Input string contains non-binary character");
        }
        cur = (((cur << 1) | (c - '0')) & mask);
        if (!seen[cur]) {
            seen[cur] = true;
            if (++found == totalCodes) {
                return true;
            }
        }
    }

    return found == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int total = 1 << k;  // number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;  // keep only k bits
    int val = 0;
    int countSeen = 0;
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            // invalid character encountered; this string cannot contain all binary codes
            return false;
        }
        val = ((val << 1) & mask) | (c - '0');
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                countSeen++;
                if (countSeen == total) {
                    return true;  // early exit when all codes are found
                }
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0 || s == null) return false;
    int n = s.length();
    if (n < k) return false;
    // If k is too large to even consider (2^k would be > possible distinct substrings)
    if (k >= 63) return false; // shift beyond 63 bits is undefined
    long totalCodes = 1L << k;
    if (totalCodes > (long) (n - k + 1)) return false; // impossible to have all distinct codes
    long mask = (k == 64) ? -1L : (1L << k) - 1; // mask to keep only k bits
    java.util.HashSet<Long> seen = new java.util.HashSet<>(1 << Math.min(k, 20) + 1);
    long val = 0;
    // build first value
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen.add(val);
    // slide through the rest
    for (int i = k; i < n; i++) {
        val = ((val << 1) | (s.charAt(i) - '0')) & mask;
        seen.add(val);
        if (seen.size() == totalCodes) return true; // early exit
    }
    return seen.size() == totalCodes;
}

