    int balance = 0;        // number of unmatched '(' seen so far
    int insertions = 0;     // number of insertions performed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // Need to insert a '(' before this ')'
                insertions++;
                balance = 1;    // the inserted '(' is now unmatched
            }
            balance--;            // match the current ')'
        } else {
