public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    long result;
    if ((n & 1) == 0) {
        long half = n / 2L;
        result = half * half;
    } else {
        long left = (n - 1L) / 2L;
        long right = (n + 1L) / 2L;
        result = left * right;
    }
    return (int) result;
}

