public int minOperations(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("n must be positive");
    }
    // Compute the number of indices that will have values greater than the target n (which is the average).
    int s = (n + 1) / 2;          // indices from s to n-1 are excess
    int operations = s * (n - s); // total units to move
    return operations;
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    // Use long for intermediate calculations to avoid overflow
    long count = n / 2L;                     // Number of surplus indices
    long start = (n + 1L) / 2L;              // First surplus index
    long end = n - 1L;                       // Last index
    long sumI = (start + end) * count / 2L;   // Sum of indices from start to end
    long result = 2L * sumI - (n - 1L) * count;
    // If the computed result exceeds int range, clamp to Integer.MAX_VALUE
    if (result > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
    }
    return (int) result;
}

