public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // enough for int range
    fib[0] = 1;
    fib[1] = 1;
    int countFib = 2;
    while (true) {
        int next = fib[countFib - 1] + fib[countFib - 2];
        if (next > k) {
            break;
        }
        fib[countFib++] = next;
    }
    int result = 0;
    int remaining = k;
    // Greedy: pick largest Fibonacci number <= remaining
    for (int i = countFib - 1; i >= 0; i--) {
        if (remaining >= fib[i]) {
            remaining -= fib[i];
            result++;
            if (remaining == 0) {
                break;
            }
        }
    }
    return result;
}

