public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                large.add(counterpart);
            }
        }
    }
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    }
    int idx = k - small.size();          // 1‑based index in 'large' reversed
    return large.get(large.size() - idx);
}

public int kthFactor(int n, int k) {
    // Validate input
    if (n <= 0 || k <= 0) {
        return -1;
    }

    java.util.List<Integer> smallFactors = new java.util.ArrayList<>();
    java.util.List<Integer> largeFactors = new java.util.ArrayList<>();

    // Find factors up to sqrt(n)
    for (int i = 1; i <= n / i; i++) {
        if (n % i == 0) {
            smallFactors.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                largeFactors.add(counterpart);
            }
        }
    }

    // Append large factors in reverse to maintain ascending order
    java.util.Collections.reverse(largeFactors);
    smallFactors.addAll(largeFactors);

    if (k > smallFactors.size()) {
        return -1;
    }
    return smallFactors.get(k - 1);
}

public int kthFactor(int n, int k) {
