    }
    ArrayList<Integer> small = new ArrayList<>();
    ArrayList<Integer> big = new ArrayList<>();
    for (int i = 1; (long)i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                big.add(other);
            }
        }
    }
    int smallSize = small.size();
    if (k <= smallSize) {
        return small.get(k - 1);
    }
    int remaining = k - smallSize;
    int bigSize = big.size();
    if (remaining > bigSize) {
        return -1;
    }
    // big is in decreasing order; we need the (remaining)-th element from the end
    return big.get(bigSize - remaining);
}

