    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (stack.length() > 0) {
            char top = stack.charAt(stack.length() - 1);
            if (Math.abs(top - c) == 32) {   // opposite case letters
                stack.deleteCharAt(stack.length() - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int[] best = {0};
    java.util.HashSet<String> used = new java.util.HashSet<>();
    java.util.function.BiConsumer<Integer, Integer> dfs = new java.util.function.BiConsumer<Integer,Integer>() {
        @Override
        public void accept(Integer idx, Integer cnt) {
            if (idx == n) {
                if (cnt > best[0]) best[0] = cnt;
                return;
            }
            // Prune if even splitting every remaining character cannot surpass current best
            if (cnt + (n - idx) <= best[0]) return;
            for (int end = idx + 1; end <= n; end++) {
                String sub = s.substring(idx, end);
                if (!used.contains(sub)) {
                    used.add(sub);
                    accept(end, cnt + 1);
                    used.remove(sub);
                }
            }
        }
    };
    dfs.accept(0, 0);
    return best[0];
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] max = {0};
    dfs(0, new java.util.HashSet<>(), s, max);
    return max[0];
}

private void dfs(int idx, java.util.Set<String> used, String s, int[] max) {
    if (idx == s.length()) {
        max[0] = Math.max(max[0], used.size());
        return;
    }
    for (int end = idx + 1; end <= s.length(); end++) {
        String sub = s.substring(idx, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, used, s, max);
            used.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int maxParts = 1;
    int maxMask = 1 << (n - 1); // number of ways to put cuts between characters
    for (int mask = 0; mask < maxMask; mask++) {
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        int start = 0;
        boolean ok = true;
        // Process cuts indicated by bits
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) {
                String part = s.substring(start, i + 1);
                if (!seen.add(part)) {
                    ok = false;
                    break; // duplicate found, this partition invalid
                }
                start = i + 1;
            }
        }
        if (!ok) {
            continue;
        }
        // Add the final part
        String lastPart = s.substring(start, n);
        if (!seen.add(lastPart)) {
            continue; // duplicate in the final part
        }
        int partsCount = seen.size(); // same as number of cuts + 1, all unique
        if (partsCount > maxParts) {
            maxParts = partsCount;
        }
    }
    return maxParts;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    final int[] best = {0};
    java.util.Set<String> used = new java.util.HashSet<>();
    class Solver {
        void dfs(int idx) {
            if (idx == n) {
                if (used.size() > best[0]) {
                    best[0] = used.size();
                }
                return;
            }
            if (used.size() + n - idx <= best[0]) {
                return;
            }
            for (int len = 1; len <= n - idx; len++) {
                String sub = s.substring(idx, idx + len);
                if (used.contains(sub)) {
                    continue;
                }
                used.add(sub);
                dfs(idx + len);
                used.remove(sub);
            }
        }
    }
    new Solver().dfs(0);
    return best[0];
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    return dfs(0, new java.util.HashSet<>(), s);
}

private int dfs(int idx, java.util.Set<String> used, String s) {
    if (idx == s.length()) {
        return 0;
    }
    int best = -1;
    for (int end = idx + 1; end <= s.length(); end++) {
        String part = s.substring(idx, end);
        if (used.contains(part)) {
            continue;
        }
        used.add(part);
        int rest = dfs(end, used, s);
        if (rest >= 0) {
            best = Math.max(best, 1 + rest);
        }
        used.remove(part);
    }
    return best;
}

