public String getSmallestString(int n, int k) {
    if (n <= 0 || k < n || k > 26 * n) {
        throw new IllegalArgumentException("Invalid values for n or k");
    }
    int remaining = k - n; // additional value we need to distribute over 'a's
    char[] result = new char[n];
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can increase up to 25 ('a'->'z')
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    // positions that were not modified remain as 'a'
    for (int i = 0; i < n; i++) {
        if (result[i] == 0) {
            result[i] = 'a';
        }
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    // Validate inputs: length must be positive and sum must be achievable
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("k must be between n and 26*n");
    }

    // Initialize all characters to 'a' (value 1). The extra sum above n will be distributed later.
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - n; // amount of value we need to add to reach total k

    // Distribute the remaining value from right to left ensuring lexicographically smallest string.
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int increment = Math.min(25, remaining); // we can add at most 25 to 'a' to get 'z'
        result[i] = (char) ('a' + increment);
        remaining -= increment;
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n < 0) {
        throw new IllegalArgumentException("Negative length is not allowed");
    }
    if (n == 0) {
        if (k == 0) {
            return "";
        } else {
            throw new IllegalArgumentException("k must be 0 when length is 0");
        }
    }
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("k must be between n and 26*n inclusive");
    }

    StringBuilder sb = new StringBuilder(n);
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }

    int remaining = k - n; // amount above all 'a's

    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        sb.setCharAt(i, (char) ('a' + add));
        remaining -= add;
    }

    return sb.toString();
}

public String getSmallestString(int n, int k) {
    if (n < 0) {
        throw new IllegalArgumentException("String length n must be non-negative");
    }
    // Minimum and maximum possible sums
    long minSum = n;            // all 'a'
    long maxSum = 26L * n;      // all 'z'
    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException("k must be between " + minSum + " and " + maxSum);
    }
    if (n == 0) {
        return "";
    }
    char[] result = new char[n];
    // Initialize with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // how much we need to add over the 'a's
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(remaining, 25); // can add at most 25 to turn an 'a' into a 'z'
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("k is out of valid range for given n");
    }
    char[] result = new char[n];
    // start with all 'a'
    java.util.Arrays.fill(result, 'a');
    int remaining = k - n; // how many extra points we can distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(26 - 1, remaining); // maximum we can add to this position
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

