public static int singleNumber(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int ones = 0, twos = 0;
    for (int num : nums) {
        // Update bits that have appeared twice
        twos |= ones & num;
        // Update bits that have appeared once
        ones ^= num;
        // Bits that have appeared three times should be reset in both ones and twos
        int commonMask = ones & twos;
        ones &= ~commonMask;
        twos &= ~commonMask;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must contain at least one element");
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitSum = 0;
        int bitMask = 1 << i;
        for (int num : nums) {
            bitSum += (num & bitMask) >> i;
        }
        if ((bitSum % 3) != 0) {
            result |= bitMask;
        }
    }
    // Handle the sign bit for negative numbers
    if ((result & (1 << 31)) != 0) {
        result -= 1 << 32;
    }
    return result;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int ones = 0, twos = 0;
    for (int num : nums) {
        ones = (ones ^ num) & ~twos;
        twos = (twos ^ num) & ~ones;
    }
    return ones;
}

