}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high || high < 0) {
        return result;
    }
    Queue<Long> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        if (i > high) break;
        queue.offer((long) i);
        if (i >= low) {
            result.add(i);
        }
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num == 0) {
            continue; // skip expanding 0 to avoid leading zeros
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add((int) next);
                }
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add((int) next);
                }
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    // Include 0 if it lies within the interval
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    // Edge case: if the interval contains only 0
    if (low == 0 && high == 0) {
        Collections.sort(result);
        return result;
    }

    Queue<Long> queue = new ArrayDeque<>();
    // Start BFS from digits 1 to 9
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    long max = high; // promote to long to avoid overflow in calculations

    while (!queue.isEmpty()) {
        long cur = queue.poll();
        if (cur > max) {
            continue;
        }

        if (cur >= low && cur <= max && cur <= Integer.MAX_VALUE) {
            result.add((int) cur);
        }

        long lastDigit = cur % 10;

        // Try appending (lastDigit - 1)
        if (lastDigit > 0) {
            long next = cur * 10 + (lastDigit - 1);
            if (next <= max) {
                queue.offer(next);
            }
        }

        // Try appending (lastDigit + 1)
        if (lastDigit < 9) {
            long next = cur * 10 + (lastDigit + 1);
            if (next <= max) {
                queue.offer(next);
            }
        }
    }

    Collections.sort(result);
    return result;
}

