public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> answer = new java.util.ArrayList<>();
    if (low > high) {
        return answer;
    }
    // Stepping numbers are non‑negative, so clamp low to 0
    low = Math.max(low, 0);
    java.util.Set<Integer> set = new java.util.TreeSet<>();

    // Single digit stepping numbers
    for (int i = 0; i <= 9; i++) {
        if (i < low) {
            continue;
        }
        if (i > high) {
            break;
        }
        set.add(i);
    }

    // BFS for multi‑digit stepping numbers
    java.util.Queue<Long> q = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        if (i <= high) {
            q.add((long) i);
        }
    }

    while (!q.isEmpty()) {
        long curr = q.poll();
        if (curr > high) {
            continue;
        }
        if (curr >= low) {
            set.add((int) curr);
        }
        int lastDigit = (int) (curr % 10);

        long next1 = curr * 10L + (lastDigit - 1);
        if (lastDigit > 0 && next1 <= high) {
            q.add(next1);
        }

        long next2 = curr * 10L + (lastDigit + 1);
        if (lastDigit < 9 && next2 <= high) {
            q.add(next2);
        }
    }

    answer.addAll(set);
    return answer;
}

