public static int countDigitOne(int n) {
    // If n is negative or zero, no ones appear
    if (n <= 0) {
        return 0;
    }

    long count = 0;
    long number = n;

    for (long factor = 1; factor <= number; factor *= 10) {
        // digit at the current position
        long cur = (number / factor) % 10;
        // higher part (more significant digits)
        long higher = number / (factor * 10);
        // lower part (less significant digits)
        long lower = number - (number / factor) * factor;

        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
    }

    return (int) count;
}

public static int countDigitOne(int n) {
