    while (factor <= nn) {
        long lower = nn % factor;
        long cur = (nn / factor) % 10;
        long higher = nn / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

