                dpH[i][j] = 1 + (j > 0 ? dpH[i][j - 1] : 0);
                dpV[i][j] = 1 + (i > 0 ? dpV[i - 1][j] : 0);
                dpD[i][j] = 1 + (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0);
                dpA[i][j] = 1 + (i > 0 && j < n - 1 ? dpA[i - 1][j + 1] : 0);

                int currentMax = Math.max(Math.max(dpH[i][j], dpV[i][j]),
                                          Math.max(dpD[i][j], dpA[i][j]));
