public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int allMask = (1 << n) - 1;
    // Precompute adjacency compatibility
    boolean[][] canAdj = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            canAdj[i][j] = (sqrt * sqrt == sum);
        }
    }
    java.util.HashMap<Long, Integer> memo = new java.util.HashMap<>();
    java.util.function.Function<java.util.AbstractMap.SimpleEntry<Integer, Integer>, Integer> dfs = new java.util.function.Function<>() {
        @Override
        public Integer apply(java.util.AbstractMap.SimpleEntry<Integer, Integer> state) {
            int mask = state.getKey();
            int last = state.getValue();
            if (mask == allMask) return 1;
            long key = (((long) mask) << 8) | last;
            Integer cached = memo.get(key);
            if (cached != null) return cached;
            int count = 0;
            java.util.HashSet<Integer> seen = new java.util.HashSet<>();
            for (int nxt = 0; nxt < n; nxt++) {
                if ((mask & (1 << nxt)) != 0) continue;
                if (seen.contains(A[nxt])) continue;
                if (last == -1 || canAdj[last][nxt]) {
                    count += dfs.apply(new java.util.AbstractMap.SimpleEntry<>(mask | (1 << nxt), nxt));
                }
                seen.add(A[nxt]);
            }
            memo.put(key, count);
            return count;
        }
    };
    int result = 0;
    for (int start = 0; start < n; start++) {
        result += dfs.apply(new java.util.AbstractMap.SimpleEntry<>(1 << start, start));
    }
    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Build frequency map
    java.util.Map<Integer, Integer> freqMap = new java.util.HashMap<>();
    int maxVal = 0;
    for (int v : A) {
        freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
        if (v > maxVal) maxVal = v;
    }
    int m = freqMap.size();
    int[] values = new int[m];
    int[] counts = new int[m];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> e : freqMap.entrySet()) {
        values[idx] = e.getKey();
        counts[idx] = e.getValue();
        idx++;
    }
    // Precompute perfect square sums
    int maxSum = maxVal * 2;
    java.util.Set<Integer> squares = new java.util.HashSet<>();
    for (int s = 2; s * s <= maxSum; s++) squares.add(s * s);
    boolean[][] good = new boolean[m][m];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < m; j++) {
            good[i][j] = squares.contains(values[i] + values[j]);
        }
    }
    // Encode remaining counts into a long mask (4 bits per count)
    long initialMask = 0L;
    for (int i = 0; i < m; i++) {
        initialMask |= ((long) counts[i]) << (i * 4);
    }
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    long total = 0L;
    // Start with each possible first element
    for (int i = 0; i < m; i++) {
        if (counts[i] == 0) continue;
        long newMask = decrementMask(initialMask, i);
        total += dfs(newMask, i, memo, good, m);
    }
    return (int) total;
}

private static long decrementMask(long mask, int idx) {
    int count = (int) ((mask >> (idx * 4)) & 0xFL);
    long clearMask = mask & ~(0xFULL << (idx * 4));
    return clearMask | ((long) (count - 1)) << (idx * 4);
}

private static long getCount(long mask, int idx) {
    return (mask >> (idx * 4)) & 0xFL;
}

private static long dfs(long mask, int last, java.util.Map<Long, Integer> memo,
                        boolean[][] good, int m) {
    if (mask == 0) return 1L;
    long key = (mask << 4) | last;
    Integer cached = memo.get(key);
    if (cached != null) return cached;
    long res = 0L;
    for (int i = 0; i < m; i++) {
        long cnt = getCount(mask, i);
        if (cnt == 0) continue;
        if (good[last][i]) {
            long newMask = decrementMask(mask, i);
            res += dfs(newMask, i, memo, good, m);
        }
    }
    memo.put(key, (int) res);
    return res;
}

