public static int squarePermutations(int[] A) {
    if (A == null) {
        return 0;
    }
    int n = A.length;
    if (n <= 1) {
        return 1;
    }
    // adjacency matrix: can[i][j] is true if A[i] + A[j] is a perfect square
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) {
                continue;
            }
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                can[i][j] = true;
            }
        }
    }

    Map<Long, Integer> memo = new HashMap<>();
    return dfs(0, -1, n, can, memo);
}

private static int dfs(int mask, int last, int n, boolean[][] can, Map<Long, Integer> memo) {
    long key = (((long) mask) << 5) | (last + 1);
    Integer cached = memo.get(key);
    if (cached != null) {
        return cached;
    }
    if (mask == (1 << n) - 1) {
        return 1;
    }
    int total = 0;
    for (int i = 0; i < n; i++) {
        if ((mask & (1 << i)) == 0) {
            if (last == -1 || can[last][i]) {
                total += dfs(mask | (1 << i), i, n, can, memo);
            }
        }
    }
    memo.put(key, total);
    return total;
}

