private static long countPermutations(int lastIndex, long mask, boolean[] used, int[] A,
                                       java.util.Set<Integer> squares,
                                       java.util.Map<Long, Integer> memo, long maskAll) {
    if ((mask & maskAll) == maskAll) {
        return 1;
    }
    long key = (mask << 4) | (lastIndex + 1); // encode mask and last index (+1 for no last)
    Integer cached = memo.get(key);
    if (cached != null) return cached;
    long total = 0;
    for (int i = 0; i < A.length; i++) {
        if (used[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue; // skip duplicates
        if (lastIndex != -1 && !squares.contains(A[lastIndex] + A[i])) continue;
        used[i] = true;
        total += countPermutations(i, mask | (1L << i), used, A, squares, memo, maskAll);
        used[i] = false;
    }
    memo.put(key, (int) total);
    return total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    int[] stack = new int[n];
    int top = -1;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top != -1 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = (int) area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    // Use an explicit stack to store indices of bars
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    long maxArea = 0;
    int n = heights.length;

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }

    return (int) maxArea;
}

