public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    int maxSize = Math.min(m, n);
    for (int s = 0; s <= m + n - 2; s++) {
        int[] buffer = new int[maxSize];
        int count = 0;
        for (int i = 0; i < m; i++) {
            int j = s - i;
            if (j >= 0 && j < n) {
                buffer[count++] = mat[i][j];
            }
        }
        if (s % 2 == 0) {
            for (int k = count - 1; k >= 0; k--) {
                result[idx++] = buffer[k];
            }
        } else {
            for (int k = 0; k < count; k++) {
                result[idx++] = buffer[k];
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;
    int totalDiagonals = rows + cols - 1;
    for (int sum = 0; sum < totalDiagonals; sum++) {
        int startRow = Math.max(0, sum - (cols - 1));
        int endRow = Math.min(rows - 1, sum);
        if (sum % 2 == 0) {
            for (int r = endRow; r >= startRow; r--) {
                int c = sum - r;
                result[index++] = mat[r][c];
            }
        } else {
            for (int r = startRow; r <= endRow; r++) {
                int c = sum - r;
                result[index++] = mat[r][c];
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    // Ensure matrix is rectangular
    for (int i = 1; i < m; i++) {
        if (mat[i].length != n) {
            throw new IllegalArgumentException("Matrix rows have different lengths.");
        }
    }
    int total = m * n;
    int[] result = new int[total];
    int index = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        if ((sum & 1) == 0) { // even sum: traverse from bottom to top
            int row = Math.min(sum, m - 1);
            int col = sum - row;
            while (row >= 0 && col < n) {
                result[index++] = mat[row][col];
                row--;
                col++;
            }
        } else { // odd sum: traverse from top to bottom
            int col = Math.min(sum, n - 1);
            int row = sum - col;
            while (col >= 0 && row < m) {
                result[index++] = mat[row][col];
                row++;
                col--;
            }
        }
    }
    return result;
}

