public static java.util.List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return java.util.Collections.emptyList();
    }
    return build(n, n);
}

private static java.util.List<String> build(int len, int total) {
    if (len == 0) {
        return java.util.List.of("");
    }
    if (len == 1) {
        return java.util.List.of("0", "1", "8");
    }
    java.util.List<String> inner = build(len - 2, total);
    java.util.List<String> result = new java.util.ArrayList<>(inner.size() * 5);
    for (String s : inner) {
        if (len != total) {
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }
    return result;
}

public static java.util.List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length must be positive");
    }
    java.util.List<String> result = build(n, n);
    // Ensure no empty string is returned for length > 0
    java.util.List<String> finalList = new java.util.ArrayList<>();
    for (String s : result) {
        if (!s.isEmpty()) {
            finalList.add(s);
        }
    }
    return finalList;
}

private static java.util.List<String> build(int current, int total) {
    java.util.List<String> res = new java.util.ArrayList<>();
    if (current == 0) {
        res.add("");
        return res;
    }
    if (current == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    java.util.List<String> middle = build(current - 2, total);
    char[][] pairs = { {'0', '0'}, {'1', '1'}, {'8', '8'}, {'6', '9'}, {'9', '6'} };
    for (String m : middle) {
        for (char[] p : pairs) {
            if (current == total && p[0] == '0') {
                continue; // avoid leading zero for outermost layer
            }
            res.add(p[0] + m + p[1]);
        }
    }
    return res;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }
    List<String> numbers = build(n, n);
    Collections.sort(numbers);
    return numbers;
}

private static List<String> build(int currentLen, int targetLen) {
    if (currentLen == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (currentLen == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }

    List<String> inner = build(currentLen - 2, targetLen);
    List<String> result = new ArrayList<>();
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'8', '8'}, {'6', '9'}, {'9', '6'}};

    for (String mid : inner) {
        for (char[] p : pairs) {
            if (currentLen == targetLen && p[0] == '0') {
                continue; // avoid leading zero for outermost pair
            }
            result.add(new StringBuilder().append(p[0]).append(mid).append(p[1]).toString());
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new java.util.ArrayList<>();
    }
    return build(n, n);
}

private static java.util.List<String> build(int n, int m) {
    if (n == 0) {
        return java.util.Collections.singletonList("");
    }
    if (n == 1) {
        return java.util.Arrays.asList("0", "1", "8");
    }
    java.util.List<String> prev = build(n - 2, m);
    java.util.List<String> result = new java.util.ArrayList<>();
    for (String s : prev) {
        if (n != m) {
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for duplicate points
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Compute cross product to check collinearity
    int cross = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
    return cross != 0;
}

