            return false;
        }
        p[i][0] = points[i][0];
        p[i][1] = points[i][1];
    }

    // Compute twice the area of the triangle (shoelace formula)
    long area2 = (long) p[0][0] * (p[1][1] - p[2][1])
               + (long) p[1][0] * (p[2][1] - p[0][1])
               + (long) p[2][0] * (p[0][1] - p[1][1]);

    return area2 != 0;
}

