public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    result.add(current);
    long next = (long) current * 10;
    while (next <= n && next <= Integer.MAX_VALUE) {
        dfs((int) next, n, result);
        next++;
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new java.util.ArrayList<>(n > 0 ? n : 0);
    if (n <= 0) {
        return result;
    }

    long cur = 1;
    int count = 0;
    while (count < n) {
        result.add((int) cur);
        count++;
        if (cur * 10 <= n) {
            cur *= 10;
        } else {
            if (cur % 10 != 9 && cur + 1 <= n) {
                cur++;
            } else {
                while (cur / 10 > 0 && cur % 10 == 9) {
                    cur /= 10;
                }
                cur = cur / 10 + 1;
            }
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result;
    }
    long curr = 1;
    for (int count = 0; count < n; count++) {
        result.add((int) curr);
        if (curr * 10 <= n) {
            curr *= 10;
        } else {
            if (curr % 10 != 9 && curr + 1 <= n) {
                curr++;
            } else {
                while ((curr / 10) % 10 == 9 || curr == n) {
                    curr /= 10;
                }
                curr++;
            }
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(Math.max(0, n));
    if (n <= 0) {
        return result;
    }

    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);

        if ((long) current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }

    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(Math.max(n, 0));
    if (n < 1) {
        return result;
    }
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs((long) i, n, result);
    }
    return result;
}

private static void dfs(long current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add((int) current);
    if (current * 10 <= n) { // go deeper into the same prefix
        dfs(current * 10, n, result);
    }
    long start = current * 10 + 1;
    long end = Math.min(n, current * 10 + 9);
    for (long next = start; next <= end; next++) {
        dfs(next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

