public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) return 0;
    int[] dp = new int[n + 1];
    // initialize dp array with a large value
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    // Pre-calculate all perfect squares <= n
    int maxRoot = (int) Math.sqrt(n);
    int[] squares = new int[maxRoot];
    for (int i = 1; i <= maxRoot; i++) {
        squares[i - 1] = i * i;
    }

    int[] dp = new int[n + 1];
    final int INF = n + 1; // upper bound (worst case using 1^2 repeatedly)
    for (int i = 1; i <= n; i++) {
        int min = INF;
        for (int sq : squares) {
            if (sq > i) {
                break;
            }
            int candidate = dp[i - sq] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    // Check if n is a perfect square
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }
    // Check if n can be expressed as sum of two perfect squares
    for (int i = 1; i <= sqrtN; i++) {
        int remaining = n - i * i;
        int sqrtRemain = (int) Math.sqrt(remaining);
        if (sqrtRemain * sqrtRemain == remaining) {
            return 2;
        }
    }
    // Legendre's three-square theorem: if n is of the form 4^a*(8b+7), answer is 4
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) {
        return 4;
    }
    // Otherwise, answer is 3
    return 3;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = i; // maximum number of 1^2 needed
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int sqrtN = (int) Math.sqrt(n);
    // Check if n is a perfect square
    for (int i = 1; i <= sqrtN; i++) {
        if (i * i == n) {
            return 1;
        }
    }
    // Check if n can be expressed as sum of two perfect squares
    for (int i = 1; i <= sqrtN; i++) {
        int remainder = n - i * i;
        if (remainder <= 0) {
            continue;
        }
        int sqrtRem = (int) Math.sqrt(remainder);
        if (sqrtRem * sqrtRem == remainder) {
            return 2;
        }
    }
    // Use Legendre's three-square theorem to check for 4
    int m = n;
    while (m % 4 == 0) {
        m /= 4;
    }
    if (m % 8 == 7) {
        return 4;
    }
    // Otherwise, answer is 3
    return 3;
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    s = s.trim();
    if (s.isEmpty()) {
        return s;
    }
    String[] words = s.split("\\s+");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        if (i > 0) {
            result.append(' ');
        }
        result.append(new StringBuilder(words[i]).reverse());
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    int n = s.length();
    while (i < n) {
        char c = s.charAt(i);
        if (Character.isWhitespace(c)) {
            // Preserve whitespace exactly as it appears
            result.append(c);
            i++;
        } else {
            int j = i;
            // Find end of the current word
            while (j < n && !Character.isWhitespace(s.charAt(j))) {
                j++;
            }
            // Append reversed word
            for (int k = j - 1; k >= i; k--) {
                result.append(s.charAt(k));
            }
            i = j;
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    result.append(word.reverse());
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder(s.length());
    int i = 0;
    int n = s.length();
    while (i < n) {
        char c = s.charAt(i);
        if (c != ' ') {
            int start = i;
            while (i < n && s.charAt(i) != ' ') {
                i++;
            }
            // Reverse the word from start (inclusive) to i (exclusive)
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        } else {
            // Preserve the space
            result.append(' ');
            i++;
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    int length = s.length();
    for (int i = 0; i < length; i++) {
        char c = s.charAt(i);
        if (c != ' ') {
            word.append(c);
        } else {
            if (word.length() > 0) {
                result.append(word.reverse());
                word.setLength(0);
            }
            result.append(' ');
        }
    }
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}
